-.kbd-container kbd {
-  background-color: var(--layout-background-3);
-  color: var(--layout-color-2);
-  text-transform: uppercase;
-  font-size: 0.8rem;
-  line-height: 1;
-  font-weight: bold;
-  box-shadow: inset 0 -1px 0 var(--layout-border-2);
-  border-radius: 3px;
-  display: inline-block;
-  padding: 2px 4px;
+.kbd-container {
+  display: flex;
+  align-items: center;
+  gap: 1px;
+
+  @media (-moz-platform: macos) {
+    gap: 2px;
+  }

-  &:first-of-type {
-    margin-inline-start: 6px;
+  & kbd {
+    color: inherit;
+    text-transform: uppercase;
+    font-size: 0.75rem;
+    line-height: 1;
+    font-weight: bold;
+    border: 1px solid color-mix(in srgb, var(--layout-border-2) 60%, transparent);
+    border-radius: 3px;
+    display: inline-block;
+    padding: 2px 3px;
+
+    &:first-of-type {
+      margin-inline-start: 3px;
+    }
+
+    @media (-moz-platform: macos) {
+      font-size: 0.8rem;
+    }
   }
 }
